INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36111, 'Luke 21:34', 'Luke', 21, 34, 'پام کوئ، خپل زړونه په مېلو، نشو او دنیاوي اندېښنو مه اخته کوئ، هسې نه چې هغه ورځ به ناڅاپه په تاسو راشي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_34.mp3', '', 1761754199, 1761754199),
(36112, 'Luke 21:35', 'Luke', 21, 35, 'او لکه د دام په شان به د نړۍ ټول خلک چې په هرځای کې وي راګېر کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_35.mp3', '', 1761754199, 1761754199),
(36113, 'Luke 21:36', 'Luke', 21, 36, 'نو بېدار اوسئ او هر وخت دعا کوئ، ترڅو دا توان پیدا کړئ چې د دې ټولو شیانو څخه چې ډېر زر به پېښ شي، وژغورل شئ او د انسان د زوی په مخکې ودرېدلی شئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_36.mp3', '', 1761754199, 1761754199),
(36114, 'Luke 21:37', 'Luke', 21, 37, 'عیسی به د ورځې له خوا د خدای په کور کې تعلیم ورکاوه. ماښام به وتلو او شپه به یې د زیتون په غره کې تېروله', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_37.mp3', '', 1761754199, 1761754199),
(36115, 'Luke 21:38', 'Luke', 21, 38, 'او سهار وختي به ټول خلک د خدای کور ته ورتلل چې د هغه خبرې واوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke21_verse_38.mp3', '', 1761754199, 1761754199),
(36116, 'Romans 13:1', 'Romans', 13, 1, 'هرڅوک دې د حکومتي واکمنانو تابعداري کوي، ځکه چې د خدای له اجازې پرته څوک نه شي کولای چې حکومت وکړي او اوسني واکمنان د خدای له خوا ټاکل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_1.mp3', '', 1761754199, 1761754199),
(36117, 'Romans 13:2', 'Romans', 13, 2, 'له دې امله څوک چې د واکمنانو سره مخالفت کوي، نو د خدای سره چې هغوی یې ټاکلي دي، مخالفت کوي او څوک چې مخالفت کوي، هغوی به په خپله خپل ځان ته سزا ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_2.mp3', '', 1761754199, 1761754199),
(36118, 'Romans 13:3', 'Romans', 13, 3, 'ځکه چې واکمنان د ښو خلکو د وېرې سبب نه ګرځي، بلکې بدکاران ترې وېریږي. که چېرې غواړئ چې د قدرت د خاوندانو څخه وېره ونه لرئ، نو بیا ښه کار کوئ او هغوی به ستاسو ستاینه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_3.mp3', '', 1761754199, 1761754199),
(36119, 'Romans 13:4', 'Romans', 13, 4, 'ځکه چې هغوی د خدای خدمتګاران دي او ستاسو د ښېګڼې دپاره دي. خو که چېرې تاسو غلط کار کوئ، نو بیا ووېرېږئ، ځکه چې هغوی د خپل ځان سره توره بې‌دلیله نه ګرځوي. هغوی د خدای خدمتګاران دي او د خدای د غضب له لارې بدکارانو ته سزا ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_4.mp3', '', 1761754199, 1761754199),
(36120, 'Romans 13:5', 'Romans', 13, 5, 'له همدې امله باید د واک د خاوندانو تابع اوسئ، یوازې د خدای د غضب نه د ځان ساتلو دپاره نه، بلکې د خپل وجدان په خاطر.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_5.mp3', '', 1761754199, 1761754199),
(36121, 'Romans 13:6', 'Romans', 13, 6, 'له همدې امله تاسو هم خپله مالیه ورکوئ، ځکه چې د واک خاوندان د خدای خدمتګاران دي او په خپلو دندو کې بوخت دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_6.mp3', '', 1761754199, 1761754199),
(36122, 'Romans 13:7', 'Romans', 13, 7, 'د کومو خلکو نه چې مو پور اخیستی وي، هغوی ته خپل پور بېرته ورکړئ. د مالیې اخیستونکو ته مالیه ورکوئ او محصول د محصول اخیستونکو ته ورکوئ. څوک چې د درناوي وړ وي، د هغوی درناوی کوئ او د عزت د خاوندانو عزت کوئ. د یو بل په وړاندې زمونږ دنده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_7.mp3', '', 1761754199, 1761754199),
(36123, 'Romans 13:8', 'Romans', 13, 8, 'د هېچا پور په ځان باندې مه پرېږدئ، بلکې ستاسو یوازېنی کار د یو بل سره مینه کول دي. ځکه څوک چې د نورو سره مینه کوي، هغه په شریعت باندې پوره عمل کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_8.mp3', '', 1761754199, 1761754199),
(36124, 'Romans 13:9', 'Romans', 13, 9, 'ځکه چې دا حکمونه دي: «زنا مه کوه، قتل مه کوه، غلا مه کوه، د نورو څخه د کوم شي تمه مه کوه» او نور حکمونه هم دي چې په دې حکم کې په لنډه توګه بیانیږي: «د خپل ګاونډي سره د خپل ځان په شان مینه کوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_9.mp3', '', 1761754199, 1761754199),
(36125, 'Romans 13:10', 'Romans', 13, 10, 'څوک چې د خپل ګاونډي سره مینه کوي، نو د هغه سره بد نه کوي. نو له دې امله مینه کول د شریعت پوره کول دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_10.mp3', '', 1761754199, 1761754199),
(36126, 'Romans 13:11', 'Romans', 13, 11, 'همدارنګه لکه څنګه چې تاسو پوهېږئ چې همدا‌اوس هغه وخت رارسېدلی دی چې باید د خوب نه راویښ شئ. ځکه چې اوس زمونږ خلاصون د هغې ورځې نه ډېر رانژدې شوی دی چې کله مو ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_11.mp3', '', 1761754199, 1761754199),
(36127, 'Romans 13:12', 'Romans', 13, 12, 'شپه تېره شوې ده او ورځ رانژدې ده. نو راځئ چې د تیارې د کارونو نه لاس واخلو او د رڼا د زغرو کالي واغوندو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_12.mp3', '', 1761754199, 1761754199),
(36128, 'Romans 13:13', 'Romans', 13, 13, 'راځئ چې د هغو کسانو په شان چې په رڼا کې ژوند کوي، مناسب چلند وکړو، نه په عیاشۍ او نشو کې، نه په جنسي بد‌اخلاقۍ او فساد کې، نه په جګړو او کینو کې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_13.mp3', '', 1761754199, 1761754199),
(36129, 'Romans 13:14', 'Romans', 13, 14, 'د دې په ځای د څښتن عیسی مسیح د فطرت لباس واغوندئ او نور د خپلو نفساني غوښتنو د پوره کولو په فکر کې مه اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans13_verse_14.mp3', '', 1761754199, 1761754199),
(36130, 'James 4:1', 'James', 4, 1, 'ستاسو په منځ کې جنګونه او شخړې له کومه راپیدا کیږي؟ ایا هغه ستاسو د نفساني غوښتنو له امله چې په تاسو کې په جګړه کې دي، نه راپیدا کیږي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_1.mp3', '', 1761754199, 1761754199),
(36131, 'James 4:2', 'James', 4, 2, 'تاسو چې کوم شی غواړئ او هغه په لاس نه درځي، نو دې ته تیار یئ چې قتل وکړئ. تاسو د نورو سره بخیلي کوئ، خو څه چې غواړئ هغه لاسته نه شئ راوړلی، نو جنګ او شخړه کوئ. خو بیاهم کوم شی په لاس نه درځي، ځکه چې د خدای څخه یې نه غواړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_2.mp3', '', 1761754199, 1761754199),
(36132, 'James 4:3', 'James', 4, 3, 'خو که تاسو د خدای څخه د کوم شي دپاره سوال هم وکړئ، نو هغه به یې درنه کړي، ځکه چې په بد نیت او د خپلو هوسونو د پوره کولو دپاره یې غواړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_3.mp3', '', 1761754199, 1761754199),
(36133, 'James 4:4', 'James', 4, 4, 'ای بې‌ایمانه خلکو! ایا تاسو نه پوهېږئ چې د نړۍ سره دوستي کول د خدای سره دښمني کول دي؟ له دې امله څوک چې غواړي د نړۍ سره دوستي وکړي، نو هغه خپل ځان د خدای دښمن کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_4.mp3', '', 1761754199, 1761754199),
(36134, 'James 4:5', 'James', 4, 5, 'ایا تاسو ګومان کوئ چې د خدای د کلام دا وینا بېځایه ده چې وایي: «هغه روح چې خدای په مونږ کې اچولی دی هغه ډېرې سختې غوښتنې لري؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_5.mp3', '', 1761754199, 1761754199),
(36135, 'James 4:6', 'James', 4, 6, 'خو خدای په مونږ باندې زیات فضل کوي، نو له دې امله د خدای کلام وایي: خدای د کبرجنو په ضد دی، خو په عاجزانو باندې فضل کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_6.mp3', '', 1761754199, 1761754199),
(36136, 'James 4:7', 'James', 4, 7, 'نو له همدې امله د خپل خدای تابعداري کوئ او د شیطان په وړاندې ټینګ ودرېږئ، نو هغه به درڅخه وتښتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_7.mp3', '', 1761754199, 1761754199),
(36137, 'James 4:8', 'James', 4, 8, 'خپل ځانونه خدای ته ورنژدې کړئ، نو هغه به هم تاسو ته درنژدې شي. ای ګناهکارانو! خپل لاسونه د بدو کارونو څخه پاک کړئ. ای منافقانو! خپل زړونه پاک کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_8.mp3', '', 1761754199, 1761754199),
(36138, 'James 4:9', 'James', 4, 9, 'غمجن اوسئ، ویر او ژړا وکړئ. ستاسو خندا دې په ژړا بدله شي او ستاسو خوشحالي دې په غم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_9.mp3', '', 1761754199, 1761754199),
(36139, 'James 4:10', 'James', 4, 10, 'خپل ځانونه د څښتن په وړاندې عاجزان کړئ، نو هغه به تاسو سرلوړي کړي. د نورو په هکله قضاوت مه کوئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_10.mp3', '', 1761754199, 1761754199),
(36140, 'James 4:11', 'James', 4, 11, 'ای خویندو او ورونو! یو بل پسې بدې خبرې مه کوئ. څوک چې خپل ورور پسې بدې خبرې کوي او یا د هغه په هکله قضاوت کوي، نو په حقیقت کې د شریعت بد وایي او د هغه په هکله قضاوت کوي. که ته د شریعت په هکله قضاوت کوې، نو په شریعت عمل نه کوې بلکې خپل ځان د هغه نه لوړ ګڼې لکه په خپله چې قاضي یې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_11.mp3', '', 1761754199, 1761754199),
(36141, 'James 4:12', 'James', 4, 12, 'یوازې خدای دی چې هم شریعت ورکوي او هم قاضي دی. یوازې هغه دی چې دا قدرت لري چې خلک وژغوري او یا یې له منځه یوسي. نو بیا ته څوک یې چې د خپل ګاونډي په هکله قضاوت کوې؟ په لاپو وهلو باندې ویاړ مه کوئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_12.mp3', '', 1761754199, 1761754199),
(36142, 'James 4:13', 'James', 4, 13, 'ای خلکو واورئ، تاسو چې وایئ: «مونږ به نن یا سبا فلاني ښار ته لاړ شو او هلته به یو کال تېر کړو، هلته به سوداګري وکړو او ډېرې پیسې به وګټو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_13.mp3', '', 1761754199, 1761754199),
(36143, 'James 4:14', 'James', 4, 14, 'خو تاسو په دې هم نه پوهېږئ چې سبا به څه کیږي، ستاسو ژوند څه شی دی؟ هغه د بخار په شان دی چې د لږې شېبې دپاره راښکاره کیږي او بیا ورکیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_14.mp3', '', 1761754199, 1761754199),
(36144, 'James 4:15', 'James', 4, 15, 'د دې په ځای باید ووایئ: «که د څښتن رضا وي نو مونږ به ژوندي پاتې شو او دا یا هغه کار به وکړو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_15.mp3', '', 1761754199, 1761754199),
(36145, 'James 4:16', 'James', 4, 16, 'خو تاسو اوس په خپلو لاپو باندې ویاړ کوئ او داسې لافې وهل بد کار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_16.mp3', '', 1761754199, 1761754199),
(36146, 'James 4:17', 'James', 4, 17, 'نو بیا څوک چې په نېکۍ کولو پوهیږي او نه یې کوي، نو هغه ګناه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james4_verse_17.mp3', '', 1761754199, 1761754199),
(36147, 'John 15:1', 'John', 15, 1, 'زه د انګورو اصلي تاک یم او زما پلار باغوان دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_1.mp3', '', 1761754199, 1761754199),
(36148, 'John 15:2', 'John', 15, 2, 'زما هره څانګه چې مېوه نه نیسي هغه پرې کوي او هره څانګه چې مېوه نیسي هغه اصلاح کوي، ترڅو ډېره مېوه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_2.mp3', '', 1761754199, 1761754199),
(36149, 'John 15:3', 'John', 15, 3, 'تاسو لا د مخکې نه په هغه تعلیم باندې چې درکړی مې دی، پاک شوي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_3.mp3', '', 1761754199, 1761754199),
(36150, 'John 15:4', 'John', 15, 4, 'په ما کې پاتې شئ لکه څنګه چې زه په تاسو کې پاتې کېږم. لکه څنګه چې یوه څانګه په خپله مېوه نه شي نیولی ترڅو هغه په تاک کې پاتې نه وي، تاسو هم مېوه نه شئ نیولی ترڅو چې په ما کې پاتې نه شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_4.mp3', '', 1761754199, 1761754199),
(36151, 'John 15:5', 'John', 15, 5, 'زه د انګورو تاک یم او تاسو څانګې یئ. هرڅوک چې په ما کې پاتې شي او زه په هغه کې پاتې شم نو هغه به ډېره مېوه ونیسي، ځکه چې تاسو بې له ما هېڅ نه شئ کولای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_5.mp3', '', 1761754199, 1761754199),
(36152, 'John 15:6', 'John', 15, 6, 'که چېرې څوک په ما کې پاتې نه شي هغه به لکه بېکاره څانګه لېرې وغورځول شي او وچ به شي. هغه څانګې راټولیږي، په اور کې اچول کیږي ترڅو وسوځي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_6.mp3', '', 1761754199, 1761754199),
(36153, 'John 15:7', 'John', 15, 7, 'که چېرې تاسو په ما کې پاتې شئ او زما خبرې په تاسو کې پاتې شي، نو هرڅه چې غواړئ د هغو دپاره سوال وکړئ او هغه به درکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_7.mp3', '', 1761754199, 1761754199),
(36154, 'John 15:8', 'John', 15, 8, 'زما د پلار جلال په دې کې دی چې تاسو ډېره مېوه ونیسئ او دا ثابته کړئ چې زما شاګردان یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_8.mp3', '', 1761754199, 1761754199),
(36155, 'John 15:9', 'John', 15, 9, 'لکه څنګه چې پلار زما سره مینه کړې ده ما هم ستاسو سره مینه کړې ده. نو زما په مینه کې پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_9.mp3', '', 1761754199, 1761754199),
(36156, 'John 15:10', 'John', 15, 10, 'که چېرې تاسو زما په حکمونو باندې عمل وکړئ، نو زه به تاسو سره مینه کوم لکه څنګه چې ما د خپل پلار په حکمونو باندې عمل کړی دی او زه د هغه په مینه کې اوسېږم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_10.mp3', '', 1761754199, 1761754199),
(36157, 'John 15:11', 'John', 15, 11, 'ما دا شیان تاسو ته وویل ترڅو ستاسو زړونه زما د خوشحالۍ نه ډک شي او ستاسو خوشحالي پوره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_11.mp3', '', 1761754199, 1761754199),
(36158, 'John 15:12', 'John', 15, 12, 'زما حکم دا دی: د یو بل سره مینه کوئ لکه څنګه چې ما تاسو سره مینه کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_12.mp3', '', 1761754199, 1761754199),
(36159, 'John 15:13', 'John', 15, 13, 'د دې نه نوره زیاته مینه نشته چې یو سړی دې د خپلو ملګرو په خاطر خپل ځان قربان کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_13.mp3', '', 1761754199, 1761754199),
(36160, 'John 15:14', 'John', 15, 14, 'که چېرې تاسو زما په حکمونو باندې عمل وکړئ نو بیا به تاسو زما ملګري یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_14.mp3', '', 1761754199, 1761754199),
(36161, 'John 15:15', 'John', 15, 15, 'زه نور تاسو ته نوکران نه وایم، ځکه چې نوکران په دې نه پوهیږي چې بادار یې څه کوي، خو ما تاسو ته ملګري ویلي دي، ځکه ما چې هرڅه د خپل پلار نه اورېدلي دي هغه مې تاسو ته ویلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_15.mp3', '', 1761754199, 1761754199),
(36162, 'John 15:16', 'John', 15, 16, 'تاسو زه نه یم غوره کړی، بلکې ما تاسو غوره کړي یئ او دا کار مې درته سپارلی دی چې لاړ شئ او مېوه ونیسئ، داسې مېوه چې دوامداره وي. نو بیا چې تاسو هرڅه زما په نوم د پلار نه وغواړئ هغه به تاسو ته درکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_16.mp3', '', 1761754199, 1761754199),
(36163, 'John 15:17', 'John', 15, 17, 'نو زه تاسو ته دا حکم کوم چې د یو بل سره مینه کوئ. د نړۍ خلک به ستاسو نه کرکه کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_17.mp3', '', 1761754199, 1761754199),
(36164, 'John 15:18', 'John', 15, 18, 'که چېرې د نړۍ خلک ستاسو نه کرکه کوي، نو پوه شئ چې ستاسو نه لومړی یې زما نه کرکه کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_18.mp3', '', 1761754199, 1761754199),
(36165, 'John 15:19', 'John', 15, 19, 'که چېرې تاسو د دې نړۍ وای نو تاسو به د دې نړۍ د خلکو سره مینه کولی، خو څرنګه چې تاسو د دې نړۍ نه یئ او تاسو مې د دې نړۍ نه غوره کړي یئ نو له همدې امله نړۍ ستاسو نه کرکه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_19.mp3', '', 1761754199, 1761754199),
(36166, 'John 15:20', 'John', 15, 20, 'ما چې کوم تعلیم تاسو ته درکړې دی هغه در په یاد کړئ چې یو نوکر د خپل بادار نه لوی نه دی. که هغوی زه ځورولی یم نو تاسو به هم وځوروي. که چېرې هغوی زما په تعلیم باندې عمل کړی وي نو ستاسو په تعلیم باندې به یې هم وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_20.mp3', '', 1761754199, 1761754199),
(36167, 'John 15:21', 'John', 15, 21, 'هغوی به ستاسو سره زما د نوم په خاطر دا هرڅه وکړي، ځکه چا چې زه رالېږلی یم هغوی هغه نه پېژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_21.mp3', '', 1761754199, 1761754199),
(36168, 'John 15:22', 'John', 15, 22, 'که چېرې زه نه وای راغلی او د هغوی سره مې خبرې نه وای کړې نو هغوی به ګناهکار نه وای. خو اوس د هغوی سره د خپلې ګناه دپاره کومه بهانه نشته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_22.mp3', '', 1761754199, 1761754199),
(36169, 'John 15:23', 'John', 15, 23, 'څوک چې زما نه کرکه کوي نو هغه زما د پلار نه هم کرکه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_23.mp3', '', 1761754199, 1761754199),
(36170, 'John 15:24', 'John', 15, 24, 'که چېرې ما د هغوی په منځ کې داسې کارونه چې کوم بل چا هېڅکله کړي نه دي، نه وای کړي نو هغوی به ګناهکاره نه وای، خو هغوی دا کارونه لیدلي دي او بیاهم هغوی زما او زما د پلار نه کرکه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_24.mp3', '', 1761754199, 1761754199),
(36171, 'John 15:25', 'John', 15, 25, 'خو د هغوی په شریعت کې چې کوم څه لیکل شوي دي هغه باید رښتیا شي: هغوی بې له کوم دلیله زما نه کرکه کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_25.mp3', '', 1761754199, 1761754199),
(36172, 'John 15:26', 'John', 15, 26, 'خو کله چې ستاسو مرسته کوونکی چې زه به یې د پلار له خوا نه تاسو ته درلېږم، راشي یعنې د حقیقت روح چې د خدای له خوا راځي، هغه به زما په هکله شاهدي ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_26.mp3', '', 1761754199, 1761754199),
(36173, 'John 15:27', 'John', 15, 27, 'او تاسو به هم زما په هکله شاهدي ورکوئ، ځکه چې تاسو له پیل نه زما سره وئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john15_verse_27.mp3', '', 1761754199, 1761754199),
(36174, 'Matthew 28:1', 'Matthew', 28, 1, 'د سبت ورځ تېره شوه او د یکشنبې سهار وختي ؤ چې مریم مجدلیه او هغه بله مریم د قبر لیدلو ته لاړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_1.mp3', '', 1761754199, 1761754199),
(36175, 'Matthew 28:2', 'Matthew', 28, 2, 'ناڅاپه یوه سخته زلزله وشوه، ځکه چې د څښتن فرښته له اسمانه راښکته شوه، قبر ته ورغله او هغه تیږه یې بېرته راورغړوله او ورباندې کښېناستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_2.mp3', '', 1761754199, 1761754199),
(36176, 'Matthew 28:3', 'Matthew', 28, 3, 'د هغې مخ د برېښنا په شان ځلېده او کالي یې د واورې په شان سپین وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_3.mp3', '', 1761754199, 1761754199),
(36177, 'Matthew 28:4', 'Matthew', 28, 4, 'ساتونکي له وېرې ولړزېدل او لکه د مړو په شان په ځمکه ولوېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_4.mp3', '', 1761754199, 1761754199),
(36178, 'Matthew 28:5', 'Matthew', 28, 5, 'خو فرښتې هغو ښځو ته وویل: «مه وېرېږئ، زه پوهېږم چې تاسو عیسی لټوئ چې په صلیب باندې ځړول شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_5.mp3', '', 1761754199, 1761754199),
(36179, 'Matthew 28:6', 'Matthew', 28, 6, 'هغه دلته نشته. لکه څنګه چې هغه خپله ویلي وو، هغه راژوندی شوی دی. راشئ او هغه ځای وګورئ چې هغه په کې پروت ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_6.mp3', '', 1761754199, 1761754199),
(36180, 'Matthew 28:7', 'Matthew', 28, 7, 'نو بیا زر لاړې شئ او د هغه شاګردانو ته ووایئ چې عیسی د مړو نه راژوندی شوی دی. ګورئ، هغه ستاسو څخه مخکې جلیل ته ځي او تاسو به یې هلته ووینئ. څه چې مې درته وویل هغه یاد ساتئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_7.mp3', '', 1761754199, 1761754199),
(36181, 'Matthew 28:8', 'Matthew', 28, 8, 'نو هغوی په بیړه د قبر څخه روانې شوې او په وېرې او ډېرې خوشحالۍ سره په منډه منډه لاړې چې شاګردان خبر کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_8.mp3', '', 1761754199, 1761754199),
(36182, 'Matthew 28:9', 'Matthew', 28, 9, 'ناڅاپه عیسی د هغوی سره مخامخ شو او ویې ویل: «سلام دې وي په تاسو!» هغوی ورغلې او د هغه په پښو کې پرېوتلې او سجده یې ورته وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_9.mp3', '', 1761754199, 1761754199),
(36183, 'Matthew 28:10', 'Matthew', 28, 10, 'بیا عیسی هغوی ته وویل: «مه وېرېږئ. لاړې شئ او زما ورونو ته ووایئ چې جلیل ته لاړ شي او هلته به ما وویني.» د ساتونکو رشوت اخیستل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_10.mp3', '', 1761754199, 1761754199),
(36184, 'Matthew 28:11', 'Matthew', 28, 11, 'په هغه وخت کې چې ښځې په لاره روانې وې، یو څو عسکره چې د قبر ساتنه یې کوله، ښار ته لاړل او څه چې پېښ شوي وو هغه یې مشرانو کاهنانو ته وویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_11.mp3', '', 1761754199, 1761754199),
(36185, 'Matthew 28:12', 'Matthew', 28, 12, 'کله چې مشرانو کاهنانو د قوم د مشرانو سره لیدنه کتنه وکړه او مشوره یې وکړه او هغوی ساتونکو ته زیات رشوت ورکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_12.mp3', '', 1761754199, 1761754199),
(36186, 'Matthew 28:13', 'Matthew', 28, 13, 'او ورته ویې ویل: «تاسو باید خلکو ته داسې ووایئ، کله چې د شپې مونږ ویده وو، نو د هغه شاګردان راغلي او د هغه مړی یې غلا کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_13.mp3', '', 1761754199, 1761754199),
(36187, 'Matthew 28:14', 'Matthew', 28, 14, 'که چېرې دا خبره د والي غوږ ته ورسیږي، نو مونږ به هغه ته قناعت ورکړو چې تاسو بې‌ګناه یئ او نه پرېږدو چې د کومې ستونزې سره مخ شئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_14.mp3', '', 1761754199, 1761754199),
(36188, 'Matthew 28:15', 'Matthew', 28, 15, 'نو ساتونکو پیسې واخیستې او څه چې ورته ویل شوي وو هماغسې یې وکړل. یهودیان تر نن ورځې پورې یو بل ته دا کیسه کوي. د عیسی له خوا نورو قومونو ته د شاګردانو لېږل (مرقوس ۱۶‏:‌۱۴‌‏-‌۱۸ او لوقا ۲۴‏:‌۳۶‌‏-‌۴۹ او یوحنا ۲۰‏:‌۱۹‌‏-‌۲۳ او د رسولانو عملونه ۱‏:‌۶‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_15.mp3', '', 1761754199, 1761754199),
(36189, 'Matthew 28:16', 'Matthew', 28, 16, 'بیا یوولس شاګردان د جلیل هغه غره ته لاړل چې عیسی ورته ویلي وو چې لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_16.mp3', '', 1761754199, 1761754199),
(36190, 'Matthew 28:17', 'Matthew', 28, 17, 'کله چې هغوی عیسی ولیده، نو ورته په سجده شول. خو په هغوی کې ځینې ورباندې شکمن وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_17.mp3', '', 1761754199, 1761754199),
(36191, 'Matthew 28:18', 'Matthew', 28, 18, 'بیا عیسی هغوی ته نژدې ورغی او ورته ویې ویل: «د ځمکې او اسمان ټول واک او اختیار ماته راکړل شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_18.mp3', '', 1761754199, 1761754199),
(36192, 'Matthew 28:19', 'Matthew', 28, 19, 'لاړ شئ او ټول قومونه زما پیروان کړئ او هغوی ته د پلار او زوی او روح القدس په نوم د تعمید غسل ورکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew28_verse_19.mp3', '', 1761754199, 1761754199),
