(36207, 'Philippians 2:14', 'Philippians', 2, 14, 'هر کار پرته له ګورېدلو او بحث کولو سرته ورسوئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_14.mp3', '', 1761754199, 1761754199),
(36208, 'Philippians 2:15', 'Philippians', 2, 15, 'ترڅو په دې زمانه کې چې ټول بې‌لارې او غلط خلک دي، تاسو د خدای بې‌عیبه، معصوم او لکه د خدای بې‌ګناه اولادونه اوسئ او د هغوی په منځ کې لکه د اسمان د ستورو په شان وځلېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_15.mp3', '', 1761754199, 1761754199),
(36209, 'Philippians 2:16', 'Philippians', 2, 16, 'تاسو تل د ژوندون پیغام خلکو ته ورسوئ. که چېرې داسې وکړئ، نو زه به د مسیح د راتللو په وخت کې ویاړم چې نه زما منډې بې‌ګټې شوې او نه مې خواري بېځایه لاړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_16.mp3', '', 1761754199, 1761754199),
(36210, 'Philippians 2:17', 'Philippians', 2, 17, 'حتی که چېرې لازمه وي چې زما وینه دې لکه د قربانۍ په شان ستاسو د ایمان د قربانۍ په خاطر تویه شي، نو زه به خوشحاله یم او ستاسو ټولو په خوشحالۍ کې به شریک شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_17.mp3', '', 1761754199, 1761754199);